const COOKIE_BANNER_JS = "/* Wrong Chat — website cookie & tracking consent (no pre-ticked boxes) */\n(function () {\n  var KEY = 'wc_web_cookie_consent_v1';\n  function read() { try { return JSON.parse(localStorage.getItem(KEY) || 'null'); } catch (e) { return null; } }\n  function save(v) {\n    try { localStorage.setItem(KEY, JSON.stringify({ choice: v, at: new Date().toISOString(), version: 'v1.2' })); } catch (e) {}\n    var el = document.getElementById('wc-cookie-banner');\n    if (el && el.parentNode) el.parentNode.removeChild(el);\n    try { window.dispatchEvent(new CustomEvent('wc-web-consent', { detail: v })); } catch (e) {}\n  }\n  function build() {\n    var d = document.createElement('div');\n    d.className = 'cookies'; d.id = 'wc-cookie-banner'; d.setAttribute('role','dialog');\n    d.setAttribute('aria-label','Cookie consent');\n    d.innerHTML = '<div class=\"in\">' +\n      '<p>🍪 हम आपको ट्रैक करते हैं या नहीं — यह आप तय करें। सिर्फ़ 2 टैप। ज़रूरी कुकीज़ ऐप चलाने के लिए हैं (इनसे ट्रैकिंग नहीं होती)। वैकल्पिक एनालिटिक्स सिर्फ़ आपकी मर्ज़ी से। ' +\n      '<a href=\"/cookies-policy\" style=\"font-weight:900\">पूरी कुकी पॉलिसी पढ़ें</a></p>' +\n      '<button class=\"no\" id=\"wc-cookie-essential\">सिर्फ़ ज़रूरी</button>' +\n      '<button class=\"ok\" id=\"wc-cookie-all\">सभी स्वीकारें</button>' +\n      '</div>';\n    document.body.appendChild(d);\n    document.getElementById('wc-cookie-essential').onclick = function () { save('essential_only'); };\n    document.getElementById('wc-cookie-all').onclick = function () { save('all'); };\n  }\n  function init() { if (!read()) build(); }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();\n})();\n";
