// ============================================================================
// 📲 REAL OTP LOGIN — "सिर्फ़ असली नंबर मालिक ही लॉगिन कर सके"
//    • POST /api/otp/send    { phone }        -> 6-अंकों का OTP भेजता है
//    • POST /api/otp/verify  { phone, code }  -> सही होने पर signed token देता है
//    • GET  /api/otp/status                   -> OTP चालू है या नहीं (app को बताने के लिए)
//
//    SMS भेजने के लिए नीचे के env वेरिएबल Render पर सेट करें (कोई एक):
//      OTP_PROVIDER=fast2sms   FAST2SMS_KEY=xxxxx
//      OTP_PROVIDER=msg91      MSG91_AUTHKEY=xxxxx  MSG91_TEMPLATE_ID=xxxxx
//      OTP_PROVIDER=twilio     TWILIO_SID=xxx TWILIO_TOKEN=xxx TWILIO_FROM=+1xxxx
//      OTP_PROVIDER=webhook    OTP_WEBHOOK_URL=https://... (किसी भी SMS गेटवे के लिए)
//    अगर कुछ भी सेट नहीं है -> "preview" मोड: OTP सिर्फ़ सर्वर लॉग में दिखेगा
//      (Owner Render → Logs में देखकर यूज़र को बता सकता है) — असली SMS नहीं जाएगा।
// ============================================================================

const OTP_SECRET = process.env.OTP_SECRET || "wc_otp_secret_2026_change_me";
const OTP_PROVIDER = String(process.env.OTP_PROVIDER || "").toLowerCase().trim();
const OTP_PREVIEW = process.env.OTP_PREVIEW === "1";
const OTP_TTL_MS = 5 * 60 * 1000;        // OTP 5 मिनट तक वैध
const OTP_MAX_ATTEMPTS = 5;              // 5 गलत कोशिश के बाद बंद
const OTP_RESEND_COOLDOWN_MS = 30 * 1000; // 30 सेकंड में दोबारा नहीं
const OTP_MAX_PER_HOUR = 8;              // एक नंबर पर 1 घंटे में 8 से ज़्यादा नहीं

/** { phone: { hash, expiresAt, attempts, sentAt, sentCount, hourStart } } */
const otpStore = new Map();

function otpHash(phone, code) {
  return crypto.createHmac("sha256", OTP_SECRET).update(`${phone}|${code}`).digest("hex");
}

function otpToken(phone) {
  const issued = Date.now();
  const sig = crypto.createHmac("sha256", OTP_SECRET).update(`${phone}|${issued}`).digest("hex").slice(0, 32);
  return `${issued}.${sig}`;
}

function otpTokenValid(phone, token) {
  try {
    const [issuedRaw, sig] = String(token || "").split(".");
    const issued = Number(issuedRaw);
    if (!issued || !sig) return false;
    if (Date.now() - issued > 15 * 60 * 1000) return false;
    const expect = crypto.createHmac("sha256", OTP_SECRET).update(`${phone}|${issued}`).digest("hex").slice(0, 32);
    return crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expect));
  } catch {
    return false;
  }
}

function normalizePhone(raw) {
  const digits = String(raw || "").replace(/\D/g, "");
  if (digits.length === 10) return digits;
  if (digits.length === 12 && digits.startsWith("91")) return digits.slice(2);
  if (digits.length === 11 && digits.startsWith("0")) return digits.slice(1);
  return "";
}

const OTP_PROVIDER_LABEL =
  OTP_PROVIDER === "fast2sms" && process.env.FAST2SMS_KEY ? "fast2sms"
  : OTP_PROVIDER === "msg91" && process.env.MSG91_AUTHKEY ? "msg91"
  : OTP_PROVIDER === "twilio" && process.env.TWILIO_SID && process.env.TWILIO_TOKEN ? "twilio"
  : OTP_PROVIDER === "webhook" && process.env.OTP_WEBHOOK_URL ? "webhook"
  : "preview";

/** 🧭 कौन-सा तरीका चल रहा है: smart-otp (OTP ID) / bulk-otp (वेबसाइट वेरिफिकेशन चाहिए) */
const OTP_MODE_LABEL =
  OTP_PROVIDER_LABEL === "fast2sms"
    ? (process.env.FAST2SMS_OTP_ID ? "smart-otp" : "bulk-otp")
    : OTP_PROVIDER_LABEL;

/** 🔊 आख़िरी SMS गलती — app/Owner को साफ़ कारण दिखाने के लिए */
let otpLastError = null;

function rememberOtpError(mode, data) {
  const raw = data && (data.status_code !== undefined ? data.status_code : data.statusCode);
  otpLastError = {
    at: new Date().toISOString(),
    mode,
    code: raw === undefined || raw === null ? "" : String(raw),
    message: String((data && (data.message || data.msg)) || ""),
  };
}

/** 📖 Fast2SMS गलती को आसान हिंदी में */
function otpHintFor(code, message) {
  const c = String(code || "");
  const m = String(message || "");
  if (c === "996" || /website verification|complete kyc|kyc/i.test(m)) {
    return "Fast2SMS में वेबसाइट वेरिफिकेशन / Aadhaar KYC बाकी है — fast2sms.com → OTP Message → KYC में website https://wrong-chat-skl8.onrender.com जोड़कर Aadhaar OTP से वेरिफाई करें।";
  }
  if (c === "997") return "OTP सिर्फ़ अंकों में होना चाहिए (variables_values) — सर्वर टीम को बताएँ।";
  if (c === "411") return "मोबाइल नंबर गलत है — 10 अंकों का सही नंबर डालें।";
  if (c === "412" || c === "999") return "Fast2SMS में नंबर/टेम्पलेट सेटिंग गलत है — Render → Environment जाँचें।";
  if (c === "401" || c === "403" || /authorization/i.test(m)) {
    return "Fast2SMS API की गलत या बंद है — Render → Environment में FAST2SMS_KEY बदलें।";
  }
  if (/invalid otp id/i.test(m)) {
    return "FAST2SMS_OTP_ID गलत है — Smart OTP में बना असली OTP ID डालें।";
  }
  if (/wallet|balance|insufficient|credit/i.test(m)) {
    return "Fast2SMS वॉलेट में बैलेंस कम है — रिचार्ज करें।";
  }
  return "";
}

/** 💰 Fast2SMS वॉलेट बैलेंस (60 सेकंड cache) — कोई SMS खर्च नहीं होता */
let otpWalletCache = { at: 0, data: null };
async function fast2smsWallet() {
  if (OTP_PROVIDER_LABEL !== "fast2sms" || !process.env.FAST2SMS_KEY) return null;
  if (Date.now() - otpWalletCache.at < 60000 && otpWalletCache.data) return otpWalletCache.data;
  try {
    const r = await fetch(
      "https://www.fast2sms.com/dev/wallet?authorization=" + encodeURIComponent(process.env.FAST2SMS_KEY),
      { headers: { accept: "application/json" } }
    );
    const d = await r.json().catch(() => ({}));
    const data = {
      wallet: d && d.wallet !== undefined ? String(d.wallet) : null,
      smsCount: d && d.sms_count !== undefined ? Number(d.sms_count) : null,
      ok: Boolean(d && d.return),
    };
    otpWalletCache = { at: Date.now(), data };
    return data;
  } catch {
    return otpWalletCache.data;
  }
}

/** 🗓️ रोज़ की SMS सीमा — वॉलेट को एक दिन में खत्म होने से बचाने के लिए */
const OTP_DAILY_CAP = Math.max(1, Number(process.env.OTP_DAILY_CAP || 12));
let otpDayKey = new Date().toISOString().slice(0, 10);
let otpDayCount = 0;
function otpToday() {
  const key = new Date().toISOString().slice(0, 10);
  if (key !== otpDayKey) {
    otpDayKey = key;
    otpDayCount = 0;
  }
  return otpDayCount;
}
function otpRemainingToday() {
  return Math.max(0, OTP_DAILY_CAP - otpToday());
}

/** 📴 अभी SMS असल में जा सकता है या नहीं — app इसी से OTP वाला कदम छोड़ देता है */
function smsAvailableNow() {
  if (OTP_PROVIDER_LABEL === "preview") return false;
  if (otpRemainingToday() <= 0) return false;
  const w = otpWalletCache.data;
  if (w && w.wallet !== null && Number(w.wallet) < 5) return false;
  return true;
}

/** 🔁 Smart OTP में कोड Fast2SMS बनाता है — तो जाँच भी वहीं से (verify का सही तरीका) */
async function fast2smsVerifyRemote(phone, code) {
  if (OTP_PROVIDER_LABEL !== "fast2sms" || !process.env.FAST2SMS_KEY) {
    return { ok: false, skipped: true };
  }
  try {
    const r = await fetch("https://www.fast2sms.com/dev/otp/verify", {
      method: "POST",
      headers: {
        Authorization: process.env.FAST2SMS_KEY,
        "Content-Type": "application/json",
        accept: "application/json",
      },
      body: JSON.stringify({ mobile: phone, otp: code }),
    });
    const d = await r.json().catch(() => ({}));
    return { ok: r.ok && d.return !== false, detail: d };
  } catch (e) {
    return { ok: false, error: String((e && e.message) || e) };
  }
}

async function sendSmsOtp(phone, code) {
  const msg = `${code} आपका Wrong Chat लॉगिन OTP है। किसी को न बताएँ। ${Math.round(OTP_TTL_MS / 60000)} मिनट में खत्म।`;

  try {
    if (OTP_PROVIDER_LABEL === "fast2sms") {
      // 🅰️ Smart OTP — FAST2SMS_OTP_ID सेट है तो यह रास्ता (वेबसाइट वेरिफिकेशन की ज़रूरत नहीं)
      if (process.env.FAST2SMS_OTP_ID) {
        const smartRes = await fetch("https://www.fast2sms.com/dev/otp/send", {
          method: "POST",
          headers: {
            Authorization: process.env.FAST2SMS_KEY,
            "Content-Type": "application/json",
            accept: "application/json",
          },
          body: JSON.stringify({
            otp_id: process.env.FAST2SMS_OTP_ID,
            mobile: phone,
            otp: code,
            otp_length: 6,
            otp_expiry: Math.round(OTP_TTL_MS / 60000),
          }),
        });
        const smartData = await smartRes.json().catch(() => ({}));
        const smartOk = smartRes.ok && smartData.return !== false;
        if (!smartOk) rememberOtpError("smart-otp", smartData);
        return { ok: smartOk, provider: "fast2sms", mode: "smart-otp", detail: smartData };
      }

      // 🅱️ Classic OTP route — इसके लिए Fast2SMS में वेबसाइट वेरिफिकेशन + Aadhaar KYC ज़रूरी
      const res = await fetch("https://www.fast2sms.com/dev/bulkV2", {
        method: "POST",
        headers: {
          authorization: process.env.FAST2SMS_KEY,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          route: "otp",
          variables_values: code,
          numbers: phone,
        }),
      });
      const data = await res.json().catch(() => ({}));
      const ok = res.ok && data.return !== false;
      if (ok) return { ok: true, provider: "fast2sms", mode: "bulk-otp", detail: data };
      rememberOtpError("bulk-otp", data);

      // 🅲 KYC/वेबसाइट वेरिफिकेशन बाकी (996) हो तो Quick SMS से कोशिश — ऐप आज भी चले
      const quickAllowed = String(process.env.FAST2SMS_QUICK_FALLBACK ?? "1") !== "0";
      const errCode = String((data && data.status_code) || "");
      if (quickAllowed && (errCode === "996" || /website verification|kyc/i.test(String(data && data.message)))) {
        const quickRes = await fetch("https://www.fast2sms.com/dev/bulkV2", {
          method: "POST",
          headers: {
            authorization: process.env.FAST2SMS_KEY,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            route: "q",
            message: `${code} is your Wrong Chat login OTP. Valid for ${Math.round(OTP_TTL_MS / 60000)} min. Do not share it with anyone.`,
            language: "english",
            flash: 0,
            numbers: phone,
          }),
        });
        const quickData = await quickRes.json().catch(() => ({}));
        const quickOk = quickRes.ok && quickData.return !== false;
        if (quickOk) {
          console.log(`📨 OTP Quick-SMS fallback used for +91${phone} (route otp = 996)`);
          return { ok: true, provider: "fast2sms", mode: "quick-sms", detail: quickData };
        }
      }
      return { ok: false, provider: "fast2sms", mode: "bulk-otp", detail: data };
    }

    if (OTP_PROVIDER_LABEL === "msg91") {
      const res = await fetch("https://control.msg91.com/api/v5/otp", {
        method: "POST",
        headers: { authkey: process.env.MSG91_AUTHKEY, "Content-Type": "application/json" },
        body: JSON.stringify({
          template_id: process.env.MSG91_TEMPLATE_ID,
          mobile: `91${phone}`,
          otp: code,
          otp_expiry: Math.round(OTP_TTL_MS / 60000),
        }),
      });
      const data = await res.json().catch(() => ({}));
      return { ok: res.ok, provider: "msg91", detail: data };
    }

    if (OTP_PROVIDER_LABEL === "twilio") {
      const sid = process.env.TWILIO_SID;
      const token = process.env.TWILIO_TOKEN;
      const body = new URLSearchParams({
        To: `+91${phone}`,
        From: process.env.TWILIO_FROM,
        Body: msg,
      });
      const res = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`, {
        method: "POST",
        headers: {
          Authorization: "Basic " + Buffer.from(`${sid}:${token}`).toString("base64"),
          "Content-Type": "application/x-www-form-urlencoded",
        },
        body,
      });
      const data = await res.json().catch(() => ({}));
      return { ok: res.ok, provider: "twilio", detail: data?.sid || data };
    }

    if (OTP_PROVIDER_LABEL === "webhook") {
      const res = await fetch(process.env.OTP_WEBHOOK_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone, otp: code, message: msg }),
      });
      return { ok: res.ok, provider: "webhook" };
    }
  } catch (err) {
    return { ok: false, provider: OTP_PROVIDER_LABEL, error: String(err && err.message) };
  }

  // preview मोड — सिर्फ़ सर्वर लॉग में
  console.log(`📲 [OTP PREVIEW] +91${phone} -> ${code}`);
  return { ok: true, provider: "preview" };
}

