app.post("/api/email-otp/send", async (req, res) => {
  const email = normalizeEmail(req.body?.email);
  if (!email) {
    return res.status(400).json({ ok: false, error: "सही ईमेल पता डालें (e.g. aapka@gmail.com)।" });
  }
  if (!EMAIL_OTP_ENABLED) {
    return res.status(503).json({
      ok: false,
      error: "ईमेल OTP अभी चालू नहीं है। PIN से लॉगिन करें या Owner को बताएँ।",
    });
  }

  const now = Date.now();
  const rec = emailOtpStore.get(email) || { sentCount: 0, attempts: 0 };
  if (rec.sentAt && now - rec.sentAt < EMAIL_OTP_COOLDOWN_MS) {
    const wait = Math.ceil((EMAIL_OTP_COOLDOWN_MS - (now - rec.sentAt)) / 1000);
    return res.status(429).json({ ok: false, error: `कृपया ${wait} सेकंड बाद दोबारा भेजें।`, retryAfterSeconds: wait });
  }
  if (emailToday() >= EMAIL_OTP_DAILY_CAP) {
    return res.status(429).json({ ok: false, error: "आज की ईमेल सीमा पूरी हो गई — कल फिर कोशिश करें।" });
  }

  const code = currentOtpCode(email); // 🔑 restart-प्रूफ़ कोड
  emailOtpDayCount = emailToday() + 1;
  const sent = await sendEmailOtpCode(email, code);
  if (!sent.ok) {
    console.log(`⚠️ Email OTP fail [${sent.provider}]:`, JSON.stringify(sent.detail || {}).slice(0, 200));
    return res.status(502).json({ ok: false, error: "ईमेल नहीं भेजा जा सका — थोड़ी देर बाद कोशिश करें।" });
  }

  emailOtpStore.set(email, {
    hash: emailOtpHash(email, code),
    expiresAt: now + EMAIL_OTP_TTL_MS,
    attempts: 0,
    sentAt: now,
    sentCount: (rec.sentCount || 0) + 1,
  });

  res.json({
    ok: true,
    provider: sent.provider,
    expiresInSeconds: Math.round(EMAIL_OTP_TTL_MS / 1000),
    devOtp: EMAIL_OTP_PREVIEW ? code : undefined,
    message: `कोड ${email} पर भेज दिया गया है (Spam फ़ोल्डर भी देखें)।`,
  });
});

app.post("/api/email-otp/verify", (req, res) => {
  const email = normalizeEmail(req.body?.email);
  const code = String(req.body?.code || "").replace(/\D/g, "");
  if (!email) return res.status(400).json({ ok: false, error: "ईमेल सही नहीं है।" });
  if (code.length !== 6) return res.status(400).json({ ok: false, error: "6 अंकों का कोड डालें।" });

  const rec = emailOtpStore.get(email) || { attempts: 0, sentCount: 0 };

  // 🔑 पहले stateless जाँच (सर्वर restart हो जाए तो भी कोड चलेगा)
  const statelessMatch = validOtpCodes(email).includes(code);
  // पुराना तरीका भी साथ चले (जो कोड पहले भेजे जा चुके हैं)
  const legacyMatch =
    Boolean(rec.hash) && Boolean(rec.expiresAt) && Date.now() <= rec.expiresAt && rec.hash === emailOtpHash(email, code);

  if (rec.attempts >= EMAIL_OTP_MAX_ATTEMPTS) {
    emailOtpStore.delete(email);
    return res.status(429).json({ ok: false, error: "बहुत बार गलत कोड — नया कोड माँगें।" });
  }

  if (!statelessMatch && !legacyMatch) {
    rec.attempts += 1;
    emailOtpStore.set(email, { ...rec, attempts: rec.attempts });
    return res.status(400).json({
      ok: false,
      error: `कोड नहीं मिला! बाकी कोशिशें: ${Math.max(0, EMAIL_OTP_MAX_ATTEMPTS - rec.attempts)} — नया कोड भेजें या सही 6 अंक डालें।`,
      attemptsLeft: Math.max(0, EMAIL_OTP_MAX_ATTEMPTS - rec.attempts),
    });
  }

  emailOtpStore.delete(email);
  const issued = Date.now();
  const sig = crypto
    .createHmac("sha256", OTP_SECRET)
    .update(`mail|${email}|${issued}`)
    .digest("hex")
    .slice(0, 32);
  res.json({ ok: true, token: `${issued}.${sig}`, email, verifiedAt: issued });
});

