// (3) 404 — गलत URL पर साफ़ जवाब (JSON API के लिए)
app.use((req, res, next) => {
  if (res.headersSent) return next();
  if (req.path.startsWith("/api/")) {
    return res.status(404).json({ ok: false, error: "Endpoint नहीं मिला" });
  }
  next();
});

// (4) ⛑️ सबसे ज़रूरी: कोई भी error आए तो साइट नहीं गिरेगी
app.use((err, _req, res, _next) => {
  console.error("⚠️ Request error:", err && err.message ? err.message : err);
  if (res.headersSent) return res.end();
  const tooBig = err && (err.type === "entity.too.large" || err.status === 413);
  res.status(tooBig ? 413 : 500).json({
    ok: false,
    error: tooBig ? "फ़ाइल बहुत बड़ी है (8MB से कम भेजें)" : "कुछ गड़बड़ हुई — दोबारा कोशिश करें",
  });
});

