app.get("*", (req, res) => {
  const cleanPath = req.path === "/" ? "/index.html" : req.path;
  const hit = DECODED_ASSETS.get(cleanPath) || DECODED_ASSETS.get("/index.html");
  res.setHeader("Content-Type", hit.mime);

  // 📦 gzip compression (फ़ाइलें पहले से compress हैं — CPU खर्च शून्य)
  const acceptsGzip = String(req.headers["accept-encoding"] || "").includes("gzip");
  res.setHeader("Vary", "Accept-Encoding");

  // 🗄️ caching: hashed assets = हमेशा cache, index.html = हमेशा ताज़ा
  if (cleanPath.startsWith("/assets/") && DECODED_ASSETS.has(cleanPath)) {
    res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
  } else {
    res.setHeader("Cache-Control", "no-cache, must-revalidate");
  }
  if (cleanPath === "/index.html" || !DECODED_ASSETS.has(cleanPath)) {
    // 🍪 website cookie-consent banner + legal footer link (DPDP Act 2023)
    let html = hit.buf.toString("utf8");
    if (!html.includes("/legal-web.js")) {
      html = html.replace("</body>", '<script src="/legal-web.js" defer></script></body>');
    }
    // 🔐 वेरिफिकेशन meta tag — कोड सेट होते ही अपने आप जुड़ जाता है
    if (SITE_VERIFY_CODE && !html.includes("fast2sms-site-verification")) {
      html = html.replace(
        "</head>",
        '<meta name="fast2sms-site-verification" content="' + SITE_VERIFY_CODE.replace(/"/g, "") + '" />\n</head>'
      );
    }
    res.end(html);
    return;
  }
  if (acceptsGzip && hit.gzbuf) {
    res.setHeader("Content-Encoding", "gzip");
    res.end(hit.gzbuf);
    return;
  }
  res.end(hit.buf);
});

const server = http.createServer(app);
const wss = new WebSocketServer({ server, path: "/ws" });
const socketUserMap = new Map();

function broadcastWs(payload, exclude) {
  const raw = JSON.stringify({ ...payload, relayedAt: Date.now() });
  wss.clients.forEach((client) => {
    if (client !== exclude && client.readyState === WebSocket.OPEN) client.send(raw);
  });
}

wss.on("connection", (socket) => {
  socket.send(JSON.stringify({ type: "welcome", engine: "Wrong Chat v3.1 Render Cloud Mesh", e2ee: true }));
  socket.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString());
      if (msg.type === "identify" && msg.userId) {
        socketUserMap.set(socket, String(msg.userId));
        if (db.users[msg.userId]) {
          db.users[msg.userId].online = true;
          saveDb(db);
        }
        broadcastWs({ type: "presence", userId: msg.userId, online: true }, socket);
        return;
      }
      if (msg.type === "gps_update" && msg.userId && db.users[msg.userId]) {
        db.users[msg.userId].lat = Number(msg.lat);
        db.users[msg.userId].lng = Number(msg.lng);
        if (msg.locationName) db.users[msg.userId].locationName = String(msg.locationName);
        saveDb(db);
      }
      broadcastWs(msg, socket);
    } catch {}
  });
  socket.on("close", () => {
    const uid = socketUserMap.get(socket);
    socketUserMap.delete(socket);
    if (uid && db.users[uid]) {
      db.users[uid].online = false;
      saveDb(db);
      broadcastWs({ type: "presence", userId: uid, online: false });
    }
  });
});

// 🧯 Render/Cloudflare के पीछे 502 न आए — Node की default 5s timeout बढ़ाएँ
server.keepAliveTimeout = 65000;
server.headersTimeout = 66000;
server.requestTimeout = 30000;

server.on("error", (err) => {
  console.error("⚠️ Server error:", err && err.message ? err.message : err);
});

server.listen(PORT, HOST, () => {
  console.log("✨ Wrong Chat v3.8.4 Server LIVE (location connect key + ai repair) http://" + HOST + ":" + PORT);
  console.log("🛡️ Stability pack: gzip · cache · crash-guard · keep-alive · /api/ping");
});

// 🧯 कोई अनदेखी गलती आए तो भी प्रोसेस बंद न हो (Node 18+ में डिफ़ॉल्ट = क्रैश)
process.on("unhandledRejection", (reason) => {
  console.error("⚠️ Unhandled promise rejection (साइट चालू रहेगी):", reason);
});
process.on("uncaughtException", (err) => {
  console.error("⚠️ Uncaught exception (साइट चालू रहेगी):", err && err.stack ? err.stack : err);
});

// 🔁 हर 6 घंटे में कचरा साफ़ (मेमोरी स्थिर रहे)
setInterval(() => {
  if (global.gc) { try { global.gc(); } catch {} }
  const mem = process.memoryUsage();
  console.log("🧹 mem:", Math.round(mem.rss / 1024 / 1024), "MB · uptime:",
    Math.round((Date.now() - BOOT_TIME) / 1000 / 60), "min");
}, 6 * 60 * 60 * 1000);
